<?php declare(strict_types=1);
require dirname(__DIR__).'/native/bootstrap.php';
use Kulturhus\Native\TestSupport;
use Kulturhus\Native\Shared\{Access,Db,SecretBox};
use Kulturhus\Native\Cms\{Schema,Media,MediaMetadata,MediaUsage,MediaQuota,MediaPolicy,Pages};
use Kulturhus\Native\Web\{MediaLibrary,MediaUsagePanel};
$db=TestSupport::db();TestSupport::seed($db);Schema::install($db);$admin=new Access($db,'admin');$checks=0;
function check(bool $ok,string $label):void{global $checks;if(!$ok)throw new RuntimeException($label);$checks++;echo 'PASS '.$label."\n";}
function denied(callable $fn,string $label):void{try{$fn();}catch(DomainException|InvalidArgumentException|RuntimeException){check(true,$label);return;}throw new RuntimeException($label);}
$root=dirname(getenv('KH_NATIVE_TEST_CONFIG')).'/media-edit';mkdir($root,0700,true);$raster=imagecreatetruecolor(48,32);imagefill($raster,0,0,imagecolorallocate($raster,40,130,180));imagepng($raster,$root.'/own.png');unset($raster);
$media=new Media($db,$admin,$root.'/media');$original=$media->upload($root.'/own.png','Eigenes Original.png','Eigene Bildbeschreibung');$id=$original['id'];
$metadata=new MediaMetadata($db,$admin,new SecretBox(str_repeat('x',32)));$metadata->save($id,['alt'=>'Eigene ursprüngliche Bildbeschreibung','rights_state'=>'cleared','consent_state'=>'not_required','credit'=>'Ursprünglicher Fotocredit','source_name'=>'Eigene Kamera','license_name'=>'Eigene Nutzung'],0,'Eigener ursprünglicher privater Nachweis');
$pages=new Pages($db,$admin);$page=$pages->save(['title'=>'Eigene Veröffentlichung','slug'=>'own-photo-edit','body'=>'Eigener ursprünglicher Text','media_ids'=>[$id]]);$pages->publish($page['id'],$page['version']);$published=$pages->publicPage($page['slug']);
$originalRows=[$db->query('SELECT * FROM khcms_media ORDER BY id')->fetchAll(),$db->query('SELECT * FROM khcms_media_metadata ORDER BY media_id')->fetchAll(),$db->query('SELECT * FROM khcms_media_metadata_revisions ORDER BY media_id,version')->fetchAll(),$db->query('SELECT * FROM khcms_pages ORDER BY id')->fetchAll(),$db->query('SELECT * FROM khcms_revisions ORDER BY page_id,revision')->fetchAll()];$hashes=[];foreach(['original','large','medium','thumb']as$size)$hashes[$size]=hash_file('sha256',$media->variant($id,$size)['path']);
$quota=(new MediaQuota($db,$admin))->get();$usageBefore=(new MediaUsage($db,$admin))->listing($id)['total'];
$raster=imagecreatetruecolor(32,48);imagefill($raster,0,0,imagecolorallocate($raster,180,30,90));imagepng($raster,$root.'/own-edit.png');unset($raster);
$copy=$media->upload($root.'/own-edit.png','Eigenes Original-bearbeitet.png','Eigene ursprüngliche Bildbeschreibung',$id);
check($copy['id']!==$id&&$copy['width']===32&&$copy['height']===48,'edited pixels create a separate exact new photo');
check(count($copy['variants'])===4&&$copy['variants']['original']['derived_from']===['media_id'=>$id,'sha256'=>$original['sha256']],'new asset records exact original ID and SHA without altering variant contracts');
check($media->variant($copy['id'],'original')['name']==='Eigenes Original-bearbeitet.png','saved copy has its own readable original name');
check((new MediaMetadata($db,$admin))->get($copy['id'])['version']===0&&(new MediaMetadata($db,$admin))->get($copy['id'])['rights_state']==='unknown','copy does not manufacture original copyright approvals');
check(!(new MediaMetadata($db,$admin))->get($copy['id'])['has_proof'],'copy does not copy an encrypted consent proof');
check($pages->publicPage($page['slug'])===$published&&$media->publicVariant($id,'medium',$published)!==null,'published content and exact old original remain unchanged');
check($media->publicVariant($copy['id'],'medium')===null,'new photo remains private until consciously used and published');
$usage=(new MediaUsage($db,$admin))->listing($id);$copies=array_values(array_filter($usage['rows'],fn($r)=>$r['source']==='photo-copy'));
check($usage['total']===$usageBefore+1&&count($copies)===1&&$copies[0]['source_id']===$copy['id'],'bounded original usage retains its exact derived photo reference');
check(str_contains((new MediaUsagePanel($db,$admin,$root.'/media','own-token'))->render($id,[]),'Bearbeitetes Bild')&&str_contains((new MediaUsagePanel($db,$admin,$root.'/media','own-token'))->render($id,[]),'item='.$copy['id']),'actual usage panel opens the separate original-bound new photo');
$after=(new MediaQuota($db,$admin))->get();check($after['image_count']===$quota['image_count']+1&&$after['used_bytes']===$quota['used_bytes']+array_sum(array_column($copy['variants'],'bytes')),'copy accounts for every actual new stored variant byte');
denied(fn()=>(new Media($db,new Access($db,'reader'),$root.'/media'))->upload($root.'/own-edit.png','own.png','',$id),'reader cannot create an edited photo');
denied(fn()=>(new Media($db,new Access($db,'outsider'),$root.'/media'))->upload($root.'/own-edit.png','own.png','',$id),'foreign club cannot derive another original');
foreach(['',str_repeat('f',32),'../own',str_repeat('a',31)]as$bad)denied(fn()=>$media->upload($root.'/own-edit.png','own.png','',$bad),'missing or malformed source never writes a copy');
$ui=new MediaLibrary($db,$admin,$root.'/media','own-token');
denied(fn()=>$ui->action(['csrf'=>'bad','operation'=>'media-edit-copy','id'=>$id],[]),'copy controller requires original CSRF');
denied(fn()=>$ui->action(['csrf'=>'own-token','operation'=>'media-edit-copy','id'=>$id],['image'=>['name'=>'own.png','error'=>UPLOAD_ERR_OK,'tmp_name'=>$root.'/own-edit.png']]),'HTTP controller requires an actual uploaded file');
check(str_contains($ui->manager($id),'data-photo-copy')&&str_contains($ui->manager($id),'data-original="/media-preview/'.$id.'/original"'),'actual image editor exposes exact private source and independent edit action');
check(!str_contains((new MediaLibrary($db,new Access($db,'reader'),$root.'/media','own-token'))->manager($id),'data-photo-copy'),'reader has no editing action');
check($originalRows===[$db->query("SELECT * FROM khcms_media WHERE id='$id' ORDER BY id")->fetchAll(),$db->query('SELECT * FROM khcms_media_metadata ORDER BY media_id')->fetchAll(),$db->query('SELECT * FROM khcms_media_metadata_revisions ORDER BY media_id,version')->fetchAll(),$db->query('SELECT * FROM khcms_pages ORDER BY id')->fetchAll(),$db->query('SELECT * FROM khcms_revisions ORDER BY page_id,revision')->fetchAll()],'every original photo, metadata, approval and published row stays byte-identical');
foreach($hashes as$size=>$hash)check(hash_file('sha256',$media->variant($id,$size)['path'])===$hash,'original '.$size.' photo pixels remain byte-identical');
check($metadata->privateProof($id,1)==='Eigener ursprünglicher privater Nachweis','original encrypted consent proof retained');
(new MediaPolicy($db,$admin))->save('1','1',0);$next=$media->upload($root.'/own-edit.png','Weitere eigene Bearbeitung.png','',$id);
check((new MediaMetadata($db,$admin))->get($next['id'])['version']===0&&(new MediaMetadata($db,$admin))->get($next['id'])['rights_state']==='unknown','optional use checks never block an ordinary edited photo upload or invent a clearance');
echo $checks." original-bound edited photo checks passed; new private pixels, unchanged originals, no transport.\n";
